// ErrorCode - INVALID_REQUEST (400): malformed request
//   - INVALID_PARAMS (400): invalid function parameters or settings
//   - RESOURCE_NOT_FOUND (404): no such cell, preset, function type, ...
//   - INVALID_CELL_STATE (409): not possible in the cell's current state (e.g. Take of a cell that is not standby, standby of one that is not active)
//   - PRESET_IN_USE (409): deleting a preset in use, or changing its chain structure
//   - INVALID_CHAIN (422): the preset's chain violates a constraint (structure, format consistency)
//   - INFEASIBLE_ASSIGNMENT (422): infeasible according to pre-validation (SLA, bandwidth, SF availability, format mismatch)
//   - RESOURCE_EXHAUSTED (409): no room in a resource pool for the Take or parameter change (`details.issues` holds `ValidationIssue`s)
//   - ROUTER_ERROR (502): a router MGMT API returned an error
//   - ROUTER_TIMEOUT (504): a router MGMT API timed out
//   - INTERNAL_ERROR (500): internal IEL error
//   - NOT_IMPLEMENTED (501): an operation this IEL does not support (e.g. preset writes on an IEL that does not manage presets).
//     The UI marks the operation as unsupported and shows `message`
//
// Example: INVALID_CELL_STATE
type ErrorCode string

// ErrorResponse defines model for ErrorResponse.
type ErrorResponse struct {
	// Code - INVALID_REQUEST (400): malformed request
	// - INVALID_PARAMS (400): invalid function parameters or settings
	// - RESOURCE_NOT_FOUND (404): no such cell, preset, function type, ...
	// - INVALID_CELL_STATE (409): not possible in the cell's current state (e.g. Take of a cell that is not standby, standby of one that is not active)
	// - PRESET_IN_USE (409): deleting a preset in use, or changing its chain structure
	// - INVALID_CHAIN (422): the preset's chain violates a constraint (structure, format consistency)
	// - INFEASIBLE_ASSIGNMENT (422): infeasible according to pre-validation (SLA, bandwidth, SF availability, format mismatch)
	// - RESOURCE_EXHAUSTED (409): no room in a resource pool for the Take or parameter change (`details.issues` holds `ValidationIssue`s)
	// - ROUTER_ERROR (502): a router MGMT API returned an error
	// - ROUTER_TIMEOUT (504): a router MGMT API timed out
	// - INTERNAL_ERROR (500): internal IEL error
	// - NOT_IMPLEMENTED (501): an operation this IEL does not support (e.g. preset writes on an IEL that does not manage presets).
	//     The UI marks the operation as unsupported and shows `message`
	//
	//
	// Example: INVALID_CELL_STATE
	Code ErrorCode `json:"code"`

	// Details Extra information per error kind.
	// - PRESET_IN_USE: `{ "cell_ids": ["IN1-OUT1"] }`
	// - INVALID_CHAIN: `{ "issues": [ChainIssue] }`
	// - INFEASIBLE_ASSIGNMENT: `MatrixValidationResult`
	// - INVALID_PARAMS: `{ "errors": [FieldError] }`
	Details *map[string]interface{} `json:"details,omitempty"`

	// Message Example: IN3-OUT1 is not in standby state
	Message string `json:"message"`

	// Rollbacks Per affected cell, the rollback result of a failed router apply (502 / 504)
	Rollbacks *[]RollbackInfo `json:"rollbacks,omitempty"`
}

// ExecutionState - active: on air (at most one per OUT)
// - standby: validated and waiting (can be promoted to ACTIVE at any time)
// - off: not connected logically
// - disconnected: physical failure, signal lost
type ExecutionState string

