// ResourcePool A finite resource the streams use (static limit from the TED, usage managed by the IEL).
// There is one stream per OUT that has an ACTIVE or STANDBY cell; it is reserved at `reserved_at`
// (`standby`: when the first cell of the OUT becomes STANDBY; `on_air`: at the Take).
// Reserving and configuring are separate: VVF nodes are reserved at STANDBY, their config (parameters) is pushed at the Take.
// A `dynamic` VVF has no node in the preset; the IEL picks which node of the VVF to use at every allocation
// (a `pinned` VVF uses only the node the preset names; `VvfDefinition.allocation`).
// On every assignment, Take and parameter change the IEL allocates every stream to the pools again and, if they do not
// fit, reports `RESOURCE_EXHAUSTED` (`resource_kind` and `bottleneck_nodes`).
//
// Known kinds (more may come without schema changes; the UI shows unknown kinds with `label` and the IEL's message):
//   - `vvf_node`: a node of a processing VVF (End.AN). `sharing: same_config` (a node holds one config,
//     and only streams with the same config share it, up to capacity). `reserved_at: standby`. E.g. a transcoder has capacity 1
//   - `vvf_output`: an output of a VVF that controls the stream flow (`select` / `replicate`: switchers, ...). group is the VVF id.
//     `select` sends one selected stream per output for one OUT; `replicate` uses one per destination.
//     In a domain with `DomainPolicy.switcher_required`, every stream passes at least one `select` VVF
//   - `vvf_input`: input streams one VVF receives at once (NIC bandwidth: three 8K streams on 100G). One per input port,
//     even when several outputs use the same input
//   - `source_unicast`: streams an IN's headend can send (headend outputs). One per destination (input port of the first
//     VVF). Through a branch (`replicate`) VVF one stream reaches several OUTs
//
// `reserved_at` of the `vvf_input` / `vvf_output` and IN pools follows the network operator's setting (how STANDBY waits):
//   - `on_air` (cold standby): only ON AIR INs are sent to the switchers; the Take sets up the whole path
//   - `standby` (hot standby): STANDBY INs are also sent to the OUT's switchers, so the Take only switches.
//     Every OUT reserves one tree of switchers that receives all its ON AIR and STANDBY INs
//     (cascading receives more INs but leaves fewer switchers to other OUTs)
type ResourcePool struct {
	// Capacity Streams that can use it at once (null: no limit)
	//
	// Example: 1
	Capacity *int `json:"capacity,omitempty"`

	// Group Group of pools with the same use (VvfDefinition.id for vvf_node, null otherwise)
	//
	// Example: vvf-color-transcode-crop
	Group *string `json:"group,omitempty"`

	// Id Example: vvf_node:color-transcode-crop-1
	Id string `json:"id"`

	// Kind Kind of resource (the known values above; more may come)
	//
	// Example: vvf_node
	Kind string `json:"kind"`

	// Label Example: Color / Transcode / Crop #1
	Label string `json:"label"`

	// NodeId TED node that owns the resource (VVF node, switcher or IN id)
	//
	// Example: color-transcode-crop-1
	NodeId string `json:"node_id"`

	// ReservedAt When a stream reserves this resource
	//
	// Example: standby
	ReservedAt ResourcePoolReservedAt `json:"reserved_at"`

	// Sharing same_config: only streams with the same config (parameters) can share it
	//
	// Example: same_config
	Sharing ResourcePoolSharing `json:"sharing"`
	UsedBy  []PoolUse           `json:"used_by"`
}

// ResourcePoolReservedAt When a stream reserves this resource
//
// Example: standby
type ResourcePoolReservedAt string

// ResourcePoolSharing same_config: only streams with the same config (parameters) can share it
//
// Example: same_config
type ResourcePoolSharing string

